1	'use client'
2	
3	import { useState, useCallback, useEffect, useMemo } from 'react'
4	import { useSearchParams, useRouter } from 'next/navigation'
5	import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
6	import { toast } from 'sonner'
7	import { Button } from '@/components/ui/button'
8	import { ClientsTable } from '@/components/clients/ClientsTable'
9	import { ClientsToolbar } from '@/components/clients/ClientsToolbar'
10	import { ClientsViewTabs } from '@/components/clients/ClientsViewTabs'
11	import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
12	import type { ClientView } from '@/components/clients/SavedViewSwitcher'
13	import { SavedViewManager } from '@/components/clients/SavedViewManager'
14	import { ClientDialog } from '@/components/clients/ClientDialog'
15	import { ArchivedBanner } from '@/components/clients/ArchivedBanner'
16	import dynamic from 'next/dynamic'
17	import { Skeleton } from '@/components/ui/skeleton'
18	
19	// B3 fix: code-split Tiptap out of the /clients route initial bundle (~130KB)
20	const AddNoteModal = dynamic(
21	  () => import('@/components/clients/notes/AddNoteModal').then((m) => ({ default: m.AddNoteModal })),
22	  { ssr: false, loading: () => <Skeleton className="h-10 w-full rounded-lg" /> },
23	)
24	import { DataState } from '@/components/shared/DataState'
25	import { EmptyState } from '@/components/shared/EmptyState'
26	import { PageError } from '@/components/shared/PageError'
27	import { PullToRefresh } from '@/components/shared/PullToRefresh'
28	import { TableSkeleton } from '@/components/skeletons'
29	import type { ClientTag } from '@/components/clients/TagChip'
30	import type { Database } from '@/lib/supabase/types'
31	import type { ColumnDef } from '@/components/clients/ColumnsPicker'
32	import type { SortKey } from '@/components/clients/SortDropdown'
33	import {
34	  buildClientListSearchParams,
35	  CLIENT_LIST_PAGE_SIZE,
36	  isClientListLastVisitRange,
37	  isClientListSpendingTier,
38	  isClientListSort,
39	} from '@/lib/clients/list-query'
40	import {
41	  DEFAULT_FILTERS,
42	  type ClientFilters,
43	} from '@/components/clients/filters-types'
44	
45	type Client = Database['public']['Tables']['clients']['Row']
46	
47	// ── Column definitions ──────────────────────────────────────────────────────
48	// `defaultVisible: false` means the column is off on first load for new users;
49	// they can still toggle it on via the Columns picker and the choice persists
50	// in localStorage. Source is intentionally hidden — most studios don't look
51	// at it daily and it's available on the row profile instead.
52	const COLUMN_DEFS: ColumnDef[] = [
53	  { key: 'client',     label: 'Client',    alwaysVisible: true },
54	  { key: 'tags',       label: 'Tags' },
55	  { key: 'last_visit', label: 'Last visit' },
56	  { key: 'spent',      label: 'Spent' },
57	  { key: 'sessions',   label: 'Sessions' },
58	  { key: 'source',     label: 'Source',    defaultVisible: false },
59	  { key: 'contact',    label: 'Contact' },
60	]
61	
62	// Bumped to v2 so existing users who had source visible via the v1 default
63	// get the new default (off). They can re-enable it from the Columns picker.
64	const COLUMN_STORAGE_KEY = 'clients.columns.v2'
65	
66	function getClientListErrorMessage(payload: unknown): string | null {
67	  if (
68	    payload &&
69	    typeof payload === 'object' &&
70	    'error' in payload &&
71	    typeof payload.error === 'string'
72	  ) {
73	    return payload.error
74	  }
75	  return null
76	}
77	
78	function getDefaultVisibleKeys(): string[] {
79	  return COLUMN_DEFS.filter((c) => c.defaultVisible !== false).map((c) => c.key)
80	}
81	
82	function getInitialVisibleKeys(): string[] {
83	  if (typeof window === 'undefined') return getDefaultVisibleKeys()
84	  try {
85	    const stored = window.localStorage.getItem(COLUMN_STORAGE_KEY)
86	    if (stored) {
87	      const parsed = JSON.parse(stored) as unknown
88	      if (Array.isArray(parsed) && parsed.every((k) => typeof k === 'string')) {
89	        return parsed as string[]
90	      }
91	    }
92	  } catch {
93	    // Ignore — fall back to defaults
94	  }
95	  return getDefaultVisibleKeys()
96	}
97	
98	function toStringArray(value: unknown): string[] {
99	  if (!Array.isArray(value)) return []
100	  return value.filter((item): item is string => typeof item === 'string')
101	}
102	
103	function normalizeClientFilterTags(
104	  tags: unknown,
105	  tagLibrary: ClientTag[],
106	): string[] {
107	  return [...new Set(toStringArray(tags).map((token) => {
108	    const match = tagLibrary.find((tag) => tag.id === token || tag.name === token)
109	    return match?.name ?? token
110	  }))]
111	}
112	
113	function normalizeViewFilters(
114	  rawFilters: Partial<ClientFilters>,
115	  tagLibrary: ClientTag[],
116	): ClientFilters {
117	  const q = typeof rawFilters.q === 'string' ? rawFilters.q : ''
118	  const vip = rawFilters.vip === true
119	  const inactive = rawFilters.inactive === true
120	  const noShows = rawFilters.noShows === true
121	  const showArchived = rawFilters.showArchived === true
122	  const hasAlerts = rawFilters.hasAlerts === true
123	  const spendingTier =
124	    typeof rawFilters.spendingTier === 'string' &&
125	    isClientListSpendingTier(rawFilters.spendingTier)
126	      ? rawFilters.spendingTier
127	      : ''
128	  const lastVisitRange =
129	    typeof rawFilters.lastVisitRange === 'string' &&
130	    isClientListLastVisitRange(rawFilters.lastVisitRange)
131	      ? rawFilters.lastVisitRange
132	      : ''
133	
134	  return {
135	    ...DEFAULT_FILTERS,
136	    q,
137	    vip,
138	    inactive,
139	    noShows,
140	    showArchived,
141	    hasAlerts,
142	    spendingTier,
143	    tags: normalizeClientFilterTags(rawFilters.tags, tagLibrary),
144	    artistIds: toStringArray(rawFilters.artistIds),
145	    serviceIds: toStringArray(rawFilters.serviceIds),
146	    lastVisitRange,
147	  }
148	}
149	
150	// ────────────────────────────────────────────────────────────────────────────
151	
152	interface ClientsPageClientProps {
153	  initialClients: Client[]
154	  tagLibrary: ClientTag[]
155	  /**
156	   * Total active (non-archived) clients in the studio, computed server-side.
157	   * Distinguishes "studio has never added a client" (→ first-run onboarding)
158	   * from "studio has clients but current filter returned zero" (→ clear
159	   * filters state). Fresh value on every page load; intra-session mutations
160	   * use optimistic refresh via revalidatePath.
161	   */
162	  totalActiveClients: number
163	}
164	
165	export function ClientsPageClient({
166	  initialClients,
167	  tagLibrary,
168	  totalActiveClients,
169	}: ClientsPageClientProps) {
170	  const router = useRouter()
171	  const searchParams = useSearchParams()
172	
173	  const [clients, setClients] = useState<Client[]>(initialClients)
174	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
175	  const [selectedIds, setSelectedIds] = useState<string[]>([])
176	  const [loading, setLoading] = useState(false)
177	  const [fetchError, setFetchError] = useState<Error | null>(null)
178	  const [drawerOpen, setDrawerOpen] = useState(false)
179	  const [editingClient, setEditingClient] = useState<Client | null>(null)
180	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
181	  const [page, setPage] = useState(1)
182	  const [hasMore, setHasMore] = useState(false)
183	  const [totalCount, setTotalCount] = useState<number | null>(null)
184	
185	  // Saved views
186	  const [views, setViews] = useState<ClientView[]>([])
187	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
188	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
189	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
190	  const [editingView, setEditingView] = useState<ClientView | null>(null)
191	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
192	
193	  // Sort + column visibility
194	  const [sort, setSort] = useState<SortKey>(() => {
195	    if (typeof window !== 'undefined') {
196	      const sp = new URLSearchParams(window.location.search)
197	      const sortParam = sp.get('sort')
198	      if (sortParam && isClientListSort(sortParam)) {
199	        return sortParam
200	      }
201	    }
202	    return 'last_visit_desc'
203	  })
204	  const [visibleColumnKeys, setVisibleColumnKeys] = useState<string[]>(getInitialVisibleKeys)
205	
206	  // Persist column visibility to localStorage
207	  useEffect(() => {
208	    try {
209	      window.localStorage.setItem(COLUMN_STORAGE_KEY, JSON.stringify(visibleColumnKeys))
210	    } catch {
211	      // Ignore storage errors
212	    }
213	  }, [visibleColumnKeys])
214	
215	  // Persist sort to URL
216	  useEffect(() => {
217	    router.replace(
218	      sort !== 'last_visit_desc'
219	        ? `?sort=${sort}`
220	        : (searchParams.get('page') ? `?page=${searchParams.get('page')}` : ''),
221	      { scroll: false }
222	    )
223	  // eslint-disable-next-line react-hooks/exhaustive-deps
224	  }, [sort])
225	
226	  const fetchViews = useCallback(async () => {
227	    try {
228	      const res = await fetch('/api/client-views')
229	      if (res.ok) {
230	        const json = await res.json() as { data: ClientView[] }
231	        setViews(json.data ?? [])
232	        const defaultView = json.data?.find((v) => v.is_default)
233	        if (defaultView) {
234	          setActiveViewId((prev) => prev ?? defaultView.id)
235	        }
236	      }
237	    } catch {
238	      toast.error('Failed to load views', { description: 'Using All clients as default' })
239	    }
240	  }, [])
241	
242	  useEffect(() => {
243	    void fetchViews()
244	  }, [fetchViews])
245	
246	  // Restore page from URL
247	  useEffect(() => {
248	    const p = parseInt(searchParams.get('page') ?? '1', 10)
249	    if (p > 1) {
250	      setPage(p)
251	    }
252	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
253	
254	  const fetchClients = useCallback(async (f: ClientFilters, p = 1, sortKey: SortKey = 'last_visit_desc') => {
255	    setLoading(true)
256	    setFetchError(null)
257	    try {
258	      const params = buildClientListSearchParams({
259	        filters: f,
260	        page: p,
261	        perPage: CLIENT_LIST_PAGE_SIZE,
262	        sort: sortKey,
263	      })
264	      const res = await fetch(`/api/clients?${params.toString()}`)
265	      if (!res.ok) {
266	        const payload = await res.json().catch(() => null)
267	        throw new Error(getClientListErrorMessage(payload) ?? 'Failed to load clients')
268	      }
269	      const json = await res.json() as { data: Client[]; count: number }
270	
271	      if (p === 1) {
272	        setClients(json.data ?? [])
273	      } else {
274	        setClients((prev) => [...prev, ...(json.data ?? [])])
275	      }
276	      setTotalCount(json.count ?? null)
277	      setHasMore((json.data?.length ?? 0) >= CLIENT_LIST_PAGE_SIZE)
278	    } catch (err) {
279	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
280	    } finally {
281	      setLoading(false)
282	    }
283	  }, [])
284	
285	  useEffect(() => {
286	    void fetchClients(filters, 1, sort)
287	    setPage(1)
288	    setSelectedIds([])
289	  }, [filters, sort, fetchClients])
290	
291	  function handleFiltersChange(f: ClientFilters) {
292	    setFilters(f)
293	    setHasUnsavedChanges(true)
294	  }
295	
296	  function handleViewChange(viewId: string | null) {
297	    setActiveViewId(viewId)
298	    setHasUnsavedChanges(false)
299	    const view = views.find((v) => v.id === viewId)
300	    if (view) {
301	      const viewFilters = view.filters as Partial<ClientFilters>
302	      setFilters(normalizeViewFilters(viewFilters, tagLibrary))
303	    } else {
304	      setFilters(DEFAULT_FILTERS)
305	    }
306	  }
307	
308	  async function handleDeleteView(viewId: string) {
309	    try {
310	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
311	      if (!res.ok) throw new Error('Failed to delete view')
312	      setViews((prev) => prev.filter((v) => v.id !== viewId))
313	      if (activeViewId === viewId) {
314	        const defaultView = views.find((v) => v.is_default)
315	        setActiveViewId(defaultView?.id ?? null)
316	      }
317	      toast.success('View deleted')
318	    } catch {
319	      toast.error('Failed to delete view')
320	    }
321	  }
322	
323	  async function handleDuplicateView(view: ClientView) {
324	    try {
325	      const res = await fetch('/api/client-views', {
326	        method: 'POST',
327	        headers: { 'Content-Type': 'application/json' },
328	        body: JSON.stringify({
329	          name: `${view.name} (copy)`,
330	          filters: view.filters,
331	          scope: 'private',
332	        }),
333	      })
334	      if (!res.ok) throw new Error('Failed to duplicate view')
335	      const json = await res.json() as { data: ClientView }
336	      setViews((prev) => [...prev, json.data])
337	      toast.success('View duplicated')
338	    } catch {
339	      toast.error('Failed to duplicate view')
340	    }
341	  }
342	
343	  async function handleSetDefaultView(view: ClientView) {
344	    try {
345	      const res = await fetch(`/api/client-views/${view.id}`, {
346	        method: 'PATCH',
347	        headers: { 'Content-Type': 'application/json' },
348	        body: JSON.stringify({ is_default: true }),
349	      })
350	      if (!res.ok) throw new Error('Failed to set default')
351	      setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
352	      toast.success(`"${view.name}" is now your default view`)
353	    } catch {
354	      toast.error('Failed to set default view')
355	    }
356	  }
357	
358	  function handleViewSaved(savedView: ClientView) {
359	    setViews((prev) => {
360	      const idx = prev.findIndex((v) => v.id === savedView.id)
361	      if (idx >= 0) {
362	        const next = [...prev]
363	        next[idx] = savedView
364	        return next
365	      }
366	      return [...prev, savedView]
367	    })
368	    setActiveViewId(savedView.id)
369	    setHasUnsavedChanges(false)
370	  }
371	
372	  function handleLoadMore() {
373	    const nextPage = page + 1
374	    setPage(nextPage)
375	    router.replace(`?page=${nextPage}`, { scroll: false })
376	    void fetchClients(filters, nextPage, sort)
377	  }
378	
379	  function handleEditClient(client: Client) {
380	    setEditingClient(client)
381	    setDrawerOpen(true)
382	  }
383	
384	  function handleNewClient() {
385	    setEditingClient(null)
386	    setDrawerOpen(true)
387	  }
388	
389	  function handleDrawerSuccess(client: Client) {
390	    setClients((prev) => {
391	      const idx = prev.findIndex((c) => c.id === client.id)
392	      if (idx >= 0) {
393	        const next = [...prev]
394	        next[idx] = client
395	        return next
396	      }
397	      return [client, ...prev]
398	    })
399	    void fetchClients(filters, 1, sort)
400	  }
401	
402	  const hasActiveFilters = !!(
403	    filters.q || filters.tags.length > 0 || filters.vip ||
404	    filters.inactive || filters.noShows || filters.spendingTier ||
405	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
406	  )
407	
408	  const inactiveCount = useMemo(() => {
409	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
410	    return clients.filter(
411	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
412	    ).length
413	  }, [clients])
414	
415	  const isInitialLoad = loading && clients.length === 0
416	
417	  return (
418	    <PullToRefresh
419	      onRefresh={async () => { router.refresh() }}
420	      className="flex flex-col gap-6"
421	    >
422	      {/* ── Views row + primary action ─────────────────────────────────────── */}
423	      <div className="flex items-end justify-between gap-4 border-b border-border">
424	        <div className="flex-1 min-w-0 overflow-x-auto scrollbar-none [mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)] md:[mask-image:none]">
425	          {views.length > 0 ? (
426	            <ClientsViewTabs
427	              views={views}
428	              activeViewId={activeViewId}
429	              hasUnsavedChanges={hasUnsavedChanges}
430	              onViewChange={handleViewChange}
431	              onCreateView={() => {
432	                setViewManagerMode('create')
433	                setEditingView(null)
434	                setViewManagerOpen(true)
435	              }}
436	              onEditView={(view) => {
437	                setViewManagerMode('edit')
438	                setEditingView(view)
439	                setViewManagerOpen(true)
440	              }}
441	              onDuplicateView={handleDuplicateView}
442	              onDeleteView={handleDeleteView}
443	              onSetDefault={handleSetDefaultView}
444	            />
445	          ) : (
446	            <div className="h-10" aria-hidden="true" />
447	          )}
448	        </div>
449	        <div className="flex shrink-0 items-center gap-2 pb-2">
450	          {inactiveCount > 0 && (
451	            <span
452	              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
453	              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-[11px] font-medium px-2 py-0.5 select-none"
454	            >
455	              <span className="h-1.5 w-1.5 rounded-full bg-destructive shrink-0" aria-hidden="true" />
456	              {inactiveCount} inactive
457	            </span>
458	          )}
459	          <Button size="sm" onClick={handleNewClient}>
460	            <Plus className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
461	            New client
462	          </Button>
463	        </div>
464	      </div>
465	
466	      {/* ── Toolbar row (search + filters + sort + columns) ────────────────── */}
467	      <ClientsToolbar
468	        search={filters.q}
469	        onSearchChange={(q) => handleFiltersChange({ ...filters, q })}
470	        filters={filters}
471	        onFiltersChange={handleFiltersChange}
472	        sort={sort}
473	        onSortChange={setSort}
474	        columns={COLUMN_DEFS}
475	        visibleColumnKeys={visibleColumnKeys}
476	        onVisibleColumnsChange={setVisibleColumnKeys}
477	        tagLibrary={tagLibrary}
478	        showArchived={filters.showArchived}
479	        onToggleArchived={() => handleFiltersChange({ ...filters, showArchived: !filters.showArchived })}
480	      />
481	
482	      {/* ── Archived-view banner ──────────────────────────────────────────── */}
483	      {filters.showArchived && (
484	        <ArchivedBanner
485	          {...(typeof totalCount === 'number' ? { count: totalCount } : {})}
486	          onExit={() => handleFiltersChange({ ...filters, showArchived: false })}
487	        />
488	      )}
489	
490	      {/* ── Bulk actions ───────────────────────────────────────────────────── */}
491	      {selectedIds.length > 0 && (
492	        <BulkActionsBar
493	          selectedIds={selectedIds}
494	          tagLibrary={tagLibrary}
495	          onClearSelection={() => setSelectedIds([])}
496	          onArchived={() => void fetchClients(filters, 1, sort)}
497	          onTagsApplied={() => void fetchClients(filters, 1, sort)}
498	        />
499	      )}
500	
501	      {/* ── Table / empty / error ──────────────────────────────────────────── */}
502	      <DataState
503	        data={clients}
504	        isLoading={isInitialLoad}
505	        isError={!!fetchError && clients.length === 0}
506	        error={fetchError}
507	        loadingSlot={<TableSkeleton rows={8} />}
508	        emptySlot={(() => {
509	          // Two truly distinct empty states:
510	          //
511	          //   A) Database empty, no filters, no search → "Add your first client"
512	          //      The studio has never added a client. Give them onboarding CTAs
513	          //      (manual entry + CSV import), not "clear filters" which has no
514	          //      meaning here.
515	          //
516	          //   B) Database has clients but current query returned zero →
517	          //      "No matches" with "Clear filters" (+ "Edit view filters" if a
518	          //      saved view is active with non-default filters).
519	          //
520	          //   C) Archived view returned zero → "No archived clients" — distinct
521	          //      because the user is intentionally viewing archived and should
522	          //      not be told to "add their first client."
523	          const searchActive = filters.q.trim().length > 0
524	          const dbEmpty = totalActiveClients === 0
525	
526	          if (filters.showArchived) {
527	            return (
528	              <EmptyState
529	                icon={BookmarkX}
530	                title="No archived clients"
531	                description="Archive a client from its row menu to see it here."
532	                cta={{
533	                  label: 'Back to active clients',
534	                  onClick: () => handleFiltersChange({ ...filters, showArchived: false }),
535	                }}
536	                variant="no-results"
537	              />
538	            )
539	          }
540	
541	          if (dbEmpty && !hasActiveFilters && !searchActive) {
542	            return (
543	              <EmptyState
544	                icon={Users}
545	                title="Add your first client"
546	                description="Start with a manual entry, or import everyone from a CSV."
547	                cta={{ label: '+ New client', onClick: handleNewClient }}
548	                ctaSecondary={{
549	                  label: 'Import from CSV',
550	                  onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
551	                }}
552	                variant="first-time"
553	              />
554	            )
555	          }
556	
557	          // Filter / search returned zero — offer Clear filters. If a saved
558	          // view is active, also offer Edit view filters as secondary.
559	          const activeView = activeViewId
560	            ? views.find((v) => v.id === activeViewId)
561	            : null
562	          const clearCta = {
563	            label: 'Clear filters',
564	            onClick: () => {
565	              setFilters(DEFAULT_FILTERS)
566	              setHasUnsavedChanges(false)
567	            },
568	          }
569	          if (activeView) {
570	            return (
571	              <EmptyState
572	                icon={BookmarkX}
573	                title="No clients match these filters"
574	                description={`The filters in "${activeView.name}" returned no results.`}
575	                cta={clearCta}
576	                ctaSecondary={{
577	                  label: 'Edit view filters',
578	                  onClick: () => {
579	                    setViewManagerMode('edit')
580	                    setEditingView(activeView)
581	                    setViewManagerOpen(true)
582	                  },
583	                }}
584	                variant="no-results"
585	              />
586	            )
587	          }
588	          return (
589	            <EmptyState
590	              icon={SearchX}
591	              title="No clients match these filters"
592	              description="Try different filters or clear all to see everyone."
593	              cta={clearCta}
594	              variant="no-results"
595	            />
596	          )
597	        })()}
598	        errorSlot={
599	          <PageError
600	            error={fetchError ?? new Error('Failed to load clients')}
601	            reset={() => void fetchClients(filters, 1, sort)}
602	            variant="inline"
603	          />
604	        }
605	      >
606	        {(data) => (
607	          <ClientsTable
608	            clients={data}
609	            tagLibrary={tagLibrary}
610	            loading={loading && data.length === 0}
