'use client'

import { useState } from 'react'
import { X, Tag, XCircle, Download, Archive, PencilLine, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import { Checkbox } from '@/components/ui/checkbox'
import { TagChip, type ClientTag } from './TagChip'
import { BulkEditDialog } from './BulkEditDialog'
import { cn } from '@/lib/utils'

interface BulkActionsBarProps {
  selectedIds: string[]
  tagLibrary: ClientTag[]
  onClearSelection: () => void
  onArchived: () => void
  onTagsApplied: () => void
}

export function BulkActionsBar({
  selectedIds,
  tagLibrary,
  onClearSelection,
  onArchived,
  onTagsApplied,
}: BulkActionsBarProps) {
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [isArchiving, setIsArchiving] = useState(false)
  const [isTagging, setIsTagging] = useState(false)
  const [isExporting, setIsExporting] = useState(false)
  const [editOpen, setEditOpen] = useState(false)

  async function handleApplyTags(action: 'add' | 'remove') {
    // Resolve canonical tag names — the RPC stores tag names on clients.tags
    // (JSON array of names, not IDs), so we must translate selected IDs back
    // to their canonical name strings before sending.
    const tagNames = action === 'add'
      ? tagLibrary.filter((t) => addTagIds.includes(t.id)).map((t) => t.name)
      : tagLibrary.filter((t) => removeTagIds.includes(t.id)).map((t) => t.name)

    if (tagNames.length === 0) return
    setIsTagging(true)

    try {
      const res = await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_ids: selectedIds,
          tags_to_add: action === 'add' ? tagNames : [],
          tags_to_remove: action === 'remove' ? tagNames : [],
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to update tags')
      }
      toast.success(`Tags ${action === 'add' ? 'applied' : 'removed'}`)
      if (action === 'add') setAddTagIds([])
      else setRemoveTagIds([])
      onTagsApplied()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update tags'
      toast.error(message)
    } finally {
      setIsTagging(false)
    }
  }

  async function handleArchive() {
    setIsArchiving(true)
    try {
      await Promise.all(
        selectedIds.map((id) =>
          fetch(`/api/clients/${id}`, { method: 'DELETE' })
        )
      )
      toast.success(`${selectedIds.length} client${selectedIds.length !== 1 ? 's' : ''} archived`, {
        action: {
          label: 'Undo',
          onClick: async () => {
            await Promise.all(
              selectedIds.map((id) => fetch(`/api/clients/${id}/restore`, { method: 'POST' }))
            )
            toast.success('Restored')
            onArchived()
          },
        },
      })
      onClearSelection()
      onArchived()
    } catch {
      toast.error('Failed to archive clients')
    } finally {
      setIsArchiving(false)
    }
  }

  async function handleExport() {
    setIsExporting(true)
    const toastId = toast.loading('Preparing export…')
    try {
      const ids = selectedIds.join(',')
      const res = await fetch(`/api/clients/export?ids=${ids}`)
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `clients-${new Date().toISOString().slice(0, 10)}.csv`
      a.click()
      URL.revokeObjectURL(url)
      toast.success('Downloading', { id: toastId })
    } catch {
      toast.error('Export failed', { id: toastId })
    } finally {
      setIsExporting(false)
    }
  }

  if (selectedIds.length === 0) return null

  return (
    <div
      className={cn(
        'flex items-center justify-between gap-3 px-4 py-2.5',
        'bg-primary/[0.08] border border-primary/20 rounded-lg',
        'animate-in fade-in-0 slide-in-from-top-2 duration-150'
      )}
    >
      <div className="flex items-center gap-2">
        <span className="h-2 w-2 rounded-full bg-primary" />
        <span className="text-sm font-medium">
          {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''} selected
        </span>
      </div>

      <div className="flex items-center gap-1.5">
        {/* Bulk edit (source / preferred contact / tags) */}
        <Button
          variant="outline"
          size="sm"
          className="h-9 gap-1.5"
          onClick={() => setEditOpen(true)}
        >
          <PencilLine className="h-3.5 w-3.5" />
          Edit
        </Button>

        {/* Apply tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><Tag className="h-3.5 w-3.5" />Add tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setAddTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={addTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {addTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('add')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Apply tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Remove tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><XCircle className="h-3.5 w-3.5" />Remove tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setRemoveTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={removeTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {removeTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    variant="destructive"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('remove')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Remove tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Export */}
        <Button
          variant="outline"
          size="sm"
          className="h-9 gap-1.5"
          onClick={handleExport}
          disabled={isExporting}
        >
          {isExporting ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />}
          Export CSV
        </Button>

        {/* Archive */}
        <AlertDialog>
          <AlertDialogTrigger
            render={
              <Button
                variant="outline"
                size="sm"
                className="h-9 gap-1.5"
                loading={isArchiving}
                loadingLabel="Archiving..."
              >
                <Archive className="h-3.5 w-3.5" />
                Archive
              </Button>
            }
          />
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Archive {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''}?</AlertDialogTitle>
              <AlertDialogDescription>
                They will be hidden from your client list and won&apos;t appear in new bookings. You can restore them from the archived view.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={handleArchive}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                {isArchiving ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : 'Archive'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* Clear selection */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={onClearSelection}
          aria-label="Clear selection"
        >
          <X className="h-4 w-4" />
        </Button>
      </div>

      <BulkEditDialog
        open={editOpen}
        onOpenChange={setEditOpen}
        selectedIds={selectedIds}
        tagLibrary={tagLibrary}
        onApplied={onTagsApplied}
      />
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Loader2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { TagChip, type ClientTag } from './TagChip'

const NO_CHANGE = '__no_change__'

const SOURCE_OPTIONS = [
  { value: NO_CHANGE, label: 'Leave unchanged' },
  { value: 'public_booking', label: 'Booking page' },
  { value: 'walk_in', label: 'Walk-in' },
  { value: 'referral', label: 'Referral' },
  { value: 'social_media', label: 'Social media' },
  { value: 'manual', label: 'Manual entry' },
] as const

const CONTACT_OPTIONS = [
  { value: NO_CHANGE, label: 'Leave unchanged' },
  { value: 'email', label: 'Email' },
  { value: 'sms', label: 'SMS' },
  { value: 'phone', label: 'Phone' },
  { value: 'whatsapp', label: 'WhatsApp' },
] as const

type Source = Exclude<(typeof SOURCE_OPTIONS)[number]['value'], typeof NO_CHANGE>
type Contact = Exclude<(typeof CONTACT_OPTIONS)[number]['value'], typeof NO_CHANGE>

interface BulkEditDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  selectedIds: string[]
  tagLibrary: ClientTag[]
  onApplied: () => void
}

/**
 * Multi-client editor. Lets the operator change source / preferred contact
 * and add/remove tags on a selected batch in a single submit. Destructive-
 * by-omission fields (notes, DOB, email) deliberately excluded.
 */
export function BulkEditDialog({
  open,
  onOpenChange,
  selectedIds,
  tagLibrary,
  onApplied,
}: BulkEditDialogProps) {
  const [source, setSource] = useState<Source | typeof NO_CHANGE>(NO_CHANGE)
  const [contact, setContact] = useState<Contact | typeof NO_CHANGE>(NO_CHANGE)
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [submitting, setSubmitting] = useState(false)

  function reset() {
    setSource(NO_CHANGE)
    setContact(NO_CHANGE)
    setAddTagIds([])
    setRemoveTagIds([])
  }

  function handleOpenChange(next: boolean) {
    if (!next) reset()
    onOpenChange(next)
  }

  function toggleAddTag(id: string) {
    setAddTagIds((prev) => (prev.includes(id) ? prev.filter((t) => t !== id) : [...prev, id]))
    // Mutually exclusive — don't add + remove the same tag in one submit
    setRemoveTagIds((prev) => prev.filter((t) => t !== id))
  }

  function toggleRemoveTag(id: string) {
    setRemoveTagIds((prev) => (prev.includes(id) ? prev.filter((t) => t !== id) : [...prev, id]))
    setAddTagIds((prev) => prev.filter((t) => t !== id))
  }

  const addNames = tagLibrary.filter((t) => addTagIds.includes(t.id)).map((t) => t.name)
  const removeNames = tagLibrary.filter((t) => removeTagIds.includes(t.id)).map((t) => t.name)

  const hasChanges =
    source !== NO_CHANGE ||
    contact !== NO_CHANGE ||
    addNames.length > 0 ||
    removeNames.length > 0

  async function handleSubmit() {
    if (!hasChanges) return
    setSubmitting(true)
    try {
      const payload: {
        client_ids: string[]
        source?: Source
        preferred_contact?: Contact
        tags_to_add: string[]
        tags_to_remove: string[]
      } = {
        client_ids: selectedIds,
        tags_to_add: addNames,
        tags_to_remove: removeNames,
      }
      if (source !== NO_CHANGE) payload.source = source
      if (contact !== NO_CHANGE) payload.preferred_contact = contact

      const res = await fetch('/api/clients/bulk-edit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to apply changes')
      }

      const count = selectedIds.length
      toast.success(`Updated ${count} client${count === 1 ? '' : 's'}`)
      onApplied()
      handleOpenChange(false)
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to apply changes'
      toast.error(msg)
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent
        showCloseButton={false}
        className="sm:max-w-md max-h-[85vh] flex flex-col gap-0 p-0 overflow-hidden"
      >
        <DialogHeader className="shrink-0 border-b border-border/60 px-6 py-4">
          <DialogTitle className="font-display text-[20px] leading-tight">
            Edit {selectedIds.length} client{selectedIds.length === 1 ? '' : 's'}
          </DialogTitle>
          <DialogDescription className="text-xs text-muted-foreground">
            Fields you leave unchanged won&rsquo;t be touched on any of the selected clients.
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
          <div className="space-y-1.5">
            <Label htmlFor="bulk-edit-source" className="text-sm font-medium">Source</Label>
            <Select value={source} onValueChange={(v) => setSource(v as Source | typeof NO_CHANGE)}>
              <SelectTrigger id="bulk-edit-source">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {SOURCE_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="bulk-edit-contact" className="text-sm font-medium">Preferred contact</Label>
            <Select value={contact} onValueChange={(v) => setContact(v as Contact | typeof NO_CHANGE)}>
              <SelectTrigger id="bulk-edit-contact">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {CONTACT_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {tagLibrary.length > 0 && (
            <>
              <div className="space-y-2">
                <Label className="text-sm font-medium">Add tags</Label>
                <div className="flex flex-wrap gap-1.5">
                  {tagLibrary.map((tag) => {
                    const checked = addTagIds.includes(tag.id)
                    return (
                      <button
                        key={`add-${tag.id}`}
                        type="button"
                        onClick={() => toggleAddTag(tag.id)}
                        className="inline-flex items-center gap-1.5 rounded-md border border-border/60 bg-muted/40 px-2 py-1 text-xs hover:bg-muted transition-colors"
                      >
                        <Checkbox checked={checked} className="pointer-events-none" aria-hidden />
                        <TagChip tag={tag} size="xs" />
                      </button>
                    )
                  })}
                </div>
              </div>

              <div className="space-y-2">
                <Label className="text-sm font-medium">Remove tags</Label>
                <div className="flex flex-wrap gap-1.5">
                  {tagLibrary.map((tag) => {
                    const checked = removeTagIds.includes(tag.id)
                    return (
                      <button
                        key={`remove-${tag.id}`}
                        type="button"
                        onClick={() => toggleRemoveTag(tag.id)}
                        className="inline-flex items-center gap-1.5 rounded-md border border-border/60 bg-muted/40 px-2 py-1 text-xs hover:bg-muted transition-colors"
                      >
                        <Checkbox checked={checked} className="pointer-events-none" aria-hidden />
                        <TagChip tag={tag} size="xs" />
                      </button>
                    )
                  })}
                </div>
              </div>
            </>
          )}

          {tagLibrary.length === 0 && (
            <p className="text-xs text-muted-foreground">
              No tags yet. Create tags in Settings &rsaquo; Client tags to use them here.
            </p>
          )}
        </div>

        <div className="shrink-0 border-t border-border px-6 py-4 flex gap-3">
          <Button
            variant="outline"
            onClick={() => handleOpenChange(false)}
            disabled={submitting}
            className="h-10 flex-1"
          >
            Cancel
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={submitting || !hasChanges}
            className="h-10 flex-1"
          >
            {submitting && <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" aria-hidden="true" />}
            {submitting ? 'Applying…' : 'Apply'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { Plus, Settings2, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { TagChip, resolveTagSlugs, type ClientTag } from './TagChip'

interface ClientTagEditorProps {
  clientId: string
  clientTags: string[]
  tagLibrary: ClientTag[]
  maxVisible?: number
  /**
   * Layout variant:
   *   `row` — compact inline display for the Clients table cell, `+` icon
   *   acts as the popover trigger without disturbing row click.
   *   `stacked` — wraps under a label, for profile page usage.
   */
  variant?: 'row' | 'stacked'
}

/**
 * Per-client tag editor. Shows resolved chips + a `+` trigger that opens a
 * searchable picker. Toggling a tag calls the existing bulk-tag endpoint
 * with `client_ids: [clientId]` so all writes go through one canonical
 * RPC (`bulk_tag_clients`) — no new server code.
 */
export function ClientTagEditor({
  clientId,
  clientTags,
  tagLibrary,
  maxVisible = 3,
  variant = 'row',
}: ClientTagEditorProps) {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [pending, setPending] = useState(false)

  const resolved = resolveTagSlugs(clientTags, tagLibrary)
  const visibleTags = variant === 'stacked' ? resolved : resolved.slice(0, maxVisible)
  const overflow = variant === 'stacked' ? 0 : resolved.length - maxVisible

  async function toggle(tag: ClientTag) {
    const currentlyOn = clientTags.some(
      (t) => t.toLowerCase() === tag.name.toLowerCase() || t === tag.id,
    )
    setPending(true)
    try {
      const res = await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_ids: [clientId],
          tags_to_add: currentlyOn ? [] : [tag.name],
          tags_to_remove: currentlyOn ? [tag.name] : [],
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to update tag')
      }
      router.refresh()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update tag')
    } finally {
      setPending(false)
    }
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <div
        className={
          variant === 'stacked'
            ? 'flex flex-wrap items-center gap-1.5'
            : 'flex flex-wrap items-center gap-1'
        }
      >
