        <PopoverTrigger
          render={
            <Button
              variant="ghost"
              size="icon"
              className={
                variant === 'stacked'
                  ? 'h-6 w-6 text-muted-foreground hover:text-foreground'
                  : 'h-5 w-5 opacity-0 group-hover:opacity-100 focus-visible:opacity-100 transition-opacity text-muted-foreground hover:text-foreground'
              }
              aria-label={resolved.length === 0 ? 'Add tags' : 'Edit tags'}
            >
              {pending ? <Loader2 className="h-3 w-3 animate-spin" aria-hidden="true" /> : <Plus className="h-3 w-3" aria-hidden="true" />}
            </Button>
          }
        />
      </div>

      <PopoverContent
        align="start"
        className="w-[240px] p-0"
        onClick={(e) => e.stopPropagation()}
      >
        {tagLibrary.length === 0 ? (
          <div className="p-3 text-center space-y-2">
            <p className="text-xs text-muted-foreground">No tags created yet.</p>
            <Button variant="outline" size="sm" className="h-7 text-xs gap-1" render={<Link href="/settings/tags" />}>
              <Settings2 className="h-3 w-3" aria-hidden="true" />
              Manage tags
            </Button>
          </div>
        ) : (
          <Command>
            <CommandInput placeholder="Search tags…" className="h-8" />
            <CommandList>
              <CommandEmpty>No tags match</CommandEmpty>
              <CommandGroup>
                {tagLibrary.map((tag) => {
                  const isOn = clientTags.some(
                    (t) => t.toLowerCase() === tag.name.toLowerCase() || t === tag.id,
                  )
                  return (
                    <CommandItem
                      key={tag.id}
                      onSelect={() => toggle(tag)}
                      className="flex items-center gap-2"
                    >
                      <Checkbox checked={isOn} className="pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  )
                })}
              </CommandGroup>
            </CommandList>
            <div className="border-t border-border/40 p-1.5">
              <Button
                variant="ghost"
                size="sm"
                className="w-full h-7 text-xs gap-1 justify-start text-muted-foreground"
                render={<Link href="/settings/tags" />}
              >
                <Settings2 className="h-3 w-3" aria-hidden="true" />
                Manage tags
              </Button>
            </div>
          </Command>
        )}
      </PopoverContent>
    </Popover>
  )
}

