/** Resolves raw slug strings against the studio tag library */
export function resolveTagSlugs(
  slugs: string[],
  library: ClientTag[]
): ClientTag[] {
  return slugs
    .map((slug) => library.find((t) => t.name.toLowerCase() === slug.toLowerCase() || t.id === slug))
    .filter((t): t is ClientTag => t !== undefined)
}

'use client'

import * as React from 'react'
import { Check, ChevronDown, Search } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { type ClientTag, TagChip } from './TagChip'

interface TagPickerProps {
  tags: ClientTag[]          // full library
  value: string[]            // selected tag names
  onChange: (value: string[]) => void
  placeholder?: string
  className?: string
}

export function TagPicker({ tags, value, onChange, placeholder = 'Select tags…', className }: TagPickerProps) {
  const [open, setOpen] = React.useState(false)
  const [search, setSearch] = React.useState('')

  const filtered = tags.filter((t) =>
    t.name.toLowerCase().includes(search.toLowerCase())
  )

  function toggle(name: string) {
    onChange(
      value.includes(name)
        ? value.filter((v) => v !== name)
        : [...value, name]
    )
  }

  const selectedTags = tags.filter((t) => value.includes(t.name))

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger render={
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn('h-auto min-h-9 w-full justify-start gap-1.5 flex-wrap px-3 py-1.5 font-normal', className)}
          onClick={() => setOpen(!open)}
        >
          {selectedTags.length === 0 ? (
            <span className="text-muted-foreground text-sm">{placeholder}</span>
          ) : (
            selectedTags.map((tag) => (
              <TagChip
                key={tag.id}
                tag={tag}
                size="xs"
                onRemove={() => toggle(tag.name)}
              />
            ))
          )}
          <ChevronDown className="ml-auto h-4 w-4 shrink-0 text-muted-foreground" />
        </Button>
      } />
      <PopoverContent className="w-64 p-0" align="start">
        <div className="flex items-center border-b border-border/40 px-3 py-2">
          <Search className="mr-2 h-3.5 w-3.5 text-muted-foreground shrink-0" />
          <input
            className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
            placeholder="Search tags…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="max-h-52 overflow-y-auto p-1">
          {filtered.length === 0 ? (
            <div className="py-4 text-center text-xs text-muted-foreground">No tags found</div>
          ) : (
            filtered.map((tag) => {
              const isSelected = value.includes(tag.name)
              return (
                <button
                  key={tag.id}
                  type="button"
                  onClick={() => toggle(tag.name)}
                  className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent/50 transition-colors"
                >
                  <span className={cn(`tag-chip-${tag.color}`, 'h-2 w-2 rounded-full border-0 p-0')} />
                  <span className="flex-1 text-left">{tag.name}</span>
                  {isSelected && <Check className="h-3.5 w-3.5 text-primary shrink-0" />}
                </button>
              )
            })
          )}
        </div>
        {value.length > 0 && (
          <div className="border-t border-border/40 p-1">
            <button
              type="button"
              onClick={() => onChange([])}
              className="w-full rounded-md px-2 py-1.5 text-xs text-muted-foreground hover:bg-accent/50 text-center transition-colors"
            >
              Clear all
            </button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  )
}

'use server'

import { revalidatePath } from 'next/cache'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { z } from 'zod'

type ActionResult<T = void> =
  | { ok: true; data: T }
  | { ok: false; error: string }

const quickCreateClientSchema = z.object({
  firstName: z.string().min(1, 'First name is required').max(100),
  lastName: z.string().max(100).optional(),
  phone: z.string().max(30).optional(),
  email: z.string().email('Invalid email').optional().or(z.literal('')),
})

/**
 * Minimal client creation for the inline "Create new client" dialog in the
 * New Project form. Full client creation lives at /clients/new.
 */
export async function quickCreateClientAction(
  formData: FormData
): Promise<ActionResult<{ id: string; label: string; email: string | null }>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (auth.role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }

  const raw = {
    firstName: formData.get('firstName'),
    lastName: formData.get('lastName') || undefined,
    phone: formData.get('phone') || undefined,
    email: formData.get('email') || undefined,
  }

  const parsed = quickCreateClientSchema.safeParse(raw)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()

  const { data, error } = await supabase
    .from('clients')
    .insert({
      studio_id: auth.studioId,
      first_name: parsed.data.firstName,
      last_name: parsed.data.lastName ?? null,
      phone: parsed.data.phone ?? null,
      email: parsed.data.email || null,
    })
    .select('id, first_name, last_name, email')
    .single()

  if (error || !data) {
    logger.error({ error, studioId: auth.studioId }, 'quickCreateClientAction failed')
    return { ok: false, error: 'Failed to create client' }
  }

  revalidatePath('/clients')

  const label = `${data.first_name}${data.last_name ? ` ${data.last_name}` : ''}`
  return { ok: true, data: { id: data.id, label, email: data.email } }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const BulkTagSchema = z.object({
  client_ids: z.array(z.string().uuid()).min(1).max(500),
  tags_to_add: z.array(z.string()).default([]),
  tags_to_remove: z.array(z.string()).default([]),
})

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = BulkTagSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { client_ids, tags_to_add, tags_to_remove } = parsed.data

  try {
    const supabase = await createClient()
    const { data, error } = await supabase.rpc('bulk_tag_clients', {
      p_client_ids: client_ids,
      p_tags_to_add: tags_to_add,
      p_tags_to_remove: tags_to_remove,
    })

    if (error) {
      if (error.message?.includes('forbidden')) {
        return NextResponse.json({ error: 'Forbidden: some clients are outside your studio' }, { status: 403 })
      }
      logger.error({ err: error, studioId: authUser.studioId }, 'bulk_tag_clients RPC failed')
      return NextResponse.json({ error: 'Failed to update tags' }, { status: 500 })
    }

    revalidatePath('/', 'layout')

    return NextResponse.json({ updated: data as number })
  } catch (err) {
    logger.error({ err }, 'bulk-tag POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * Bulk-edit endpoint for the Clients page. Updates a shared subset of fields
 * across multiple selected clients in a single call. Tag mutations delegate
 * to the existing `bulk_tag_clients` RPC so the JSON-array-on-clients.tags
 * write path stays canonical.
 *
 * Destructive-by-omission fields (notes, DOB, email, allergies) intentionally
 * NOT supported here — those require per-client UX.
 */

const SOURCE_VALUES = [
  'public_booking',
  'walk_in',
  'referral',
  'social_media',
  'manual',
] as const

const BulkEditSchema = z
  .object({
    client_ids: z.array(z.string().uuid()).min(1).max(500),
    source: z.enum(SOURCE_VALUES).nullable().optional(),
    preferred_contact: z.enum(['email', 'sms', 'phone', 'whatsapp']).optional(),
    tags_to_add: z.array(z.string()).max(50).default([]),
    tags_to_remove: z.array(z.string()).max(50).default([]),
  })
  .refine(
    (v) =>
      v.source !== undefined ||
      v.preferred_contact !== undefined ||
      v.tags_to_add.length > 0 ||
      v.tags_to_remove.length > 0,
    { message: 'At least one field must change' },
  )

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = BulkEditSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { client_ids, source, preferred_contact, tags_to_add, tags_to_remove } = parsed.data

  try {
    const supabase = await createClient()

    let fieldsUpdated = 0
    if (source !== undefined || preferred_contact !== undefined) {
      const updatePayload: {
        updated_at: string
        source?: string | null
        preferred_contact?: 'email' | 'sms' | 'phone' | 'whatsapp'
      } = { updated_at: new Date().toISOString() }
      if (source !== undefined) updatePayload.source = source
      if (preferred_contact !== undefined) updatePayload.preferred_contact = preferred_contact

      const { error, count } = await supabase
        .from('clients')
        .update(updatePayload, { count: 'exact' })
        .in('id', client_ids)
        .eq('studio_id', authUser.studioId)

      if (error) {
        logger.error(
          { err: error, studioId: authUser.studioId, count: client_ids.length },
          'bulk-edit field update failed',
        )
        return NextResponse.json({ error: 'Failed to update clients' }, { status: 500 })
      }
      fieldsUpdated = count ?? 0
    }

    let tagsUpdated = 0
    if (tags_to_add.length > 0 || tags_to_remove.length > 0) {
      const { data, error } = await supabase.rpc('bulk_tag_clients', {
        p_client_ids: client_ids,
        p_tags_to_add: tags_to_add,
        p_tags_to_remove: tags_to_remove,
      })

        p_client_ids: client_ids,
        p_tags_to_add: tags_to_add,
        p_tags_to_remove: tags_to_remove,
      })

      if (error) {
        if (error.message?.includes('forbidden')) {
          return NextResponse.json(
            { error: 'Forbidden: some clients are outside your studio' },
            { status: 403 },
          )
        }
        logger.error({ err: error, studioId: authUser.studioId }, 'bulk-edit tag update failed')
        return NextResponse.json({ error: 'Failed to update tags' }, { status: 500 })
      }
      tagsUpdated = (data as number | null) ?? 0
    }

    revalidatePath('/', 'layout')

    return NextResponse.json({
      updated: Math.max(fieldsUpdated, tagsUpdated),
      fields_updated: fieldsUpdated,
      tags_updated: tagsUpdated,
    })
  } catch (err) {
    logger.error({ err }, 'bulk-edit POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

