// Parse query-string booleans safely. z.coerce.boolean() is broken for URL
// params because JavaScript Boolean("false") === true. Accept only the
// canonical strings "true"/"false"; everything else (empty, missing) → undefined.
const queryBool = z
  .enum(['true', 'false'])
  .optional()
  .transform((v) => (v === undefined ? undefined : v === 'true'))

const CLIENT_LIST_LAST_VISIT_QUERY_RANGES = [
  '7d',
  '30d',
  '90d',
  '90d+',
  'never',
  'all',
] as const

const ClientListSchema = z.object({
  q: z.string().max(200).optional(),
  tags: z.string().optional(), // comma-separated tag names
  vip: queryBool,
  inactive: queryBool,
  no_show: queryBool,
  has_alerts: queryBool,
  spending: z.enum(CLIENT_LIST_SPENDING_TIERS).optional(),
  spending_min: z.coerce.number().int().min(0).optional(),
  spending_max: z.coerce.number().int().min(0).optional(),
  // Accept 'true' | 'false' | 'any'. Default to excluding archived.
  // 'any' returns archived + non-archived together.
  archived: z.enum(['true', 'false', 'any']).default('false'),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(CLIENT_LIST_PAGE_SIZE),
  sort: z.enum(CLIENT_LIST_SORT_KEYS).default('last_visit_desc'),
  // Sprint 6 filter facets (B2 blocker fix)
