export function buildClientListSearchParams({
  filters,
  page = 1,
  perPage = CLIENT_LIST_PAGE_SIZE,
  sort = 'last_visit_desc',
}: ClientListRequestContract): URLSearchParams {
  const params = new URLSearchParams()

  if (filters.q) params.set('q', filters.q)
  if (filters.tags.length) params.set('tags', filters.tags.join(','))
  if (filters.vip) params.set('vip', 'true')
  if (filters.inactive) params.set('inactive', 'true')
  if (filters.noShows) params.set('no_show', 'true')
  params.set('archived', filters.showArchived ? 'any' : 'false')
  if (filters.hasAlerts) params.set('has_alerts', 'true')
  if (filters.spendingTier) params.set('spending', filters.spendingTier)
  if (filters.artistIds.length) params.set('artist_ids', filters.artistIds.join(','))
  if (filters.serviceIds.length) params.set('service_ids', filters.serviceIds.join(','))
  if (filters.lastVisitRange) params.set('last_visit_range', filters.lastVisitRange)
  params.set('sort', sort)
  params.set('page', String(page))
  params.set('per_page', String(perPage))

  return params
}

